using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "RandomTargetCastStateJoystickAction", menuName = "Data/Battle/Actions/RandomTargetCastStateJoystickAction")]
public class RandomTargetCastStateJoystickAction : NoTargetSelectionCastStateJoystickAction
{
	[SerializeField]
	private bool randomTargetXTimes;

	protected override void HighlightTargets()
	{
		for (int i = 0; i < actionHighlightTargets.Count; i++)
		{
			actionHighlightTargets[i].GetComponentInChildren<DicePlacement>().ToggleQuestionMark(toggle: true);
		}
	}

	protected override void CastAction()
	{
		if (randomTargetXTimes)
		{
			NoTargetCastAction();
		}
		else
		{
			RandomTargetCastAction();
		}
	}
}
